28	// Render renders the interface: header, title line, viewport, footer (Rule 124).
29	// An open overlay replaces the whole thing.
30	func (a *App) Render() string {
31		if overlay := a.activeOverlay(); overlay != "" {
32			return lipgloss.Place(a.width, a.height, lipgloss.Center, lipgloss.Center, overlay,
33				lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)))
34		}
35	
36		header := a.renderHeader() + "\n" + a.renderTitleLine()
37		// The footer is rendered first: whether a bar opens it decides how the
38		// viewport closes its bottom edge.
39		footer := a.renderViewFooter()
40		barBelow := !a.frameless() && components.OpensWithBarFrame(footer)
41		body := a.renderBody(barBelow)
42		inner := fitHeight(header, body, footer, a.height)
43	
44		placed := lipgloss.Place(a.width, a.height, lipgloss.Left, lipgloss.Top, inner,
45			lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)))
46		return a.withPalette(placed)
47	}
