62	// fitHeight stacks header, body and footer in at most height lines.
63	// lipgloss.Place pads a short block but never crops a tall one, so on a very
64	// small terminal (header 8 + title 1 + the viewport's minimum + footer) the
65	// frame would be taller than the screen. The surplus is taken from the body
66	// first: the footer carries the messages, so it outranks viewport rows. The
67	// lines taken sit just above the body's last line, so the viewport's bottom
68	// border (or the junction a bar attaches to) survives the cut; a body cut
69	// entirely is simply gone. If header and footer alone are taller than the terminal, the
70	// stack is cut to its first height lines, the simplest floor. At normal
71	// heights nothing is cut.
72	func fitHeight(header, body, footer string, height int) string {
73		parts := []string{header}
74		if body != "" {
75			parts = append(parts, body)
76		}
77		if footer != "" {
78			parts = append(parts, footer)
79		}
80		lines := strings.Split(strings.Join(parts, "\n"), "\n")
81		excess := len(lines) - height
82		if height <= 0 || excess <= 0 {
83			return strings.Join(lines, "\n")
84		}
85	
86		headerLen := strings.Count(header, "\n") + 1
87		bodyLen := 0
88		if body != "" {
89			bodyLen = strings.Count(body, "\n") + 1
90		}
91		cut := min(excess, bodyLen)
92		if cut > 0 {
93			end := headerLen + bodyLen
94			if cut < bodyLen {
95				end-- // keep the body's last line
96			}
97			lines = append(lines[:end-cut], lines[end:]...)
98		}
99		if len(lines) > height {
100			lines = lines[:height]
101		}
102		return strings.Join(lines, "\n")
103	}
