164	// frameTrail asks the active view for its border trail, within the budget the
165	// theme leaves after title. It returns "" when there is no room, the view has
166	// no trail, or the trail is wider than its budget.
167	func (a *App) frameTrail(title string) string {
168		view, ok := a.views[a.currentView]
169		if !ok {
170			return ""
171		}
172		tv, ok := view.(FrameTrailView)
173		if !ok {
174			return ""
175		}
176		budget := theme.BorderTrailBudget(title, a.width)
177		if budget <= 0 {
178			return ""
179		}
180		trail := tv.FrameTrail(budget)
181		if lipgloss.Width(trail) > budget {
182			return ""
183		}
184		return trail
185	}
