187	// frameless reports whether the active view draws its own frames (see
188	// FramelessView). The default is framed.
189	func (a *App) frameless() bool {
190		view, ok := a.views[a.currentView]
191		if !ok {
192			return false
193		}
194		fv, implements := view.(FramelessView)
195		return implements && fv.Frameless()
196	}
