// TestTheDashboardClosesEveryBoxAtEveryRealisticSize (DEVDESK-743): the router's
// viewport does not scroll, so a grid taller than the viewport silently loses
// its last lines, here the bottom border of the lowest boxes. From 24 rows up,
// every box the dashboard shows is closed, whatever the dashboard chooses to
// show at that size.
func TestTheDashboardClosesEveryBoxAtEveryRealisticSize(t *testing.T) {
	for _, width := range []int{80, 100, 120, 175, 200} {
		worst := 0
		for height := 24; height <= 60; height++ {
			a := dashboardAt(t, width, height)
			screen := a.Render()
			if n := unclosedBoxes(screen); n != 0 {
				worst = height
				if height == 24 || height == 38 {
					t.Logf("%dx%d:\n%s", width, height, ansi.Strip(screen))
				}
				_ = strings.TrimSpace
			}
		}
		if worst != 0 {
			t.Errorf("width %d: boxes lose their bottom border up to %d rows", width, worst)
		}
	}
}

